import{z as A,x as B,o as s,c as d,q as r,j as o,D as E,d as t,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"一致性哈希在数据库","description":"","frontmatter":{"title":"一致性哈希在数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/db-consistent-hashing.md","filePath":"cs/db-consistent-hashing.md","lastUpdated":1791063341000}'),p={name:"cs/db-consistent-hashing.md"};function h(c,a,m,D,u,f){const n=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="一致性哈希在数据库" tabindex="-1">一致性哈希在数据库 <a class="header-anchor" href="#一致性哈希在数据库" aria-label="Permalink to &quot;一致性哈希在数据库&quot;">​</a></h1><div class="epigraph"><p>节点与键放在环上，加节点只搬邻居区间。虚拟节点把负载摊匀。数据库用它当分片函数，仍要处理范围查询与事务。</p><footer>—— 据 Karger et al. consistent hashing；计算机栏一致性哈希课接到分片；Cassandra</footer></div><p><a href="/cs/distributed-deadlock">上一课</a>处理跨节点等待。本课不 probe。缺口是再平衡搬家量：模 \\(N\\) 哈希在 \\(N{+}1\\) 时几乎全搬。一致性哈希（consistent hashing）让加删节点只影响环上相邻键。计算机课已有 <a href="/cs/consistent-hashing">一致性哈希</a>；数据库进阶接到副本、虚节点、与范围分片对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环：节点哈希到圆，键顺时针找后继。虚拟节点：每物理机多个点，改善均匀。缺口是 <strong>SQL 范围</strong>：环打散键则 <code>BETWEEN</code> 打全体节点，与范围分片相反。事务：跨相邻虚节点仍可能跨物理机。副本：后继 \\(R\\) 个节点存副本，故障沿环走——与 Paxos 组划分不同。</p><p><span class="marginnote">把哈希空间想成钟面：每台机器、每个键都被针扎在某个时刻位置上；一个键顺时针走，碰到的第一台机器就是它的主人。加一台新机器只是插进某个时刻点，它只接管顺时针到下一台机器之间那一小段键。</span></p><p>再平衡：新节点从后继偷走一段，拷贝时双路由，同再平衡课。</p><p><span class="marginnote">Karger et al. 一致性哈希（DHT 谱系）。Cassandra 令牌环是数据库著名实现。本课不重推哈希函数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选：写均匀、节点频繁进出 → 环。范围扫描、时间局部 → 范围分片。混合：先租户范围再租户内哈希。查询路由：协调器算令牌。二级索引仍头痛。</p><p>与缓冲：无关直接。与 LSM：各节点本地 LSM，环只定键归属。</p>',11)),(s(),o(l,null,{default:E(()=>[i(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E9%94%AE%E5%93%88%E5%B8%8C%E4%B8%8A%E7%8E%AF%22%5D%20--%3E%20N%5B%22%E5%90%8E%E7%BB%A7%E8%8A%82%E7%82%B9%22%5D%0A%20%20ADD%5B%22%E5%8A%A0%E8%8A%82%E7%82%B9%22%5D%20--%3E%20MV%5B%22%E5%8F%AA%E6%90%AC%E9%82%BB%E6%8E%A5%E5%BC%A7%22%5D%0A%20%20RNG%5B%22%E8%8C%83%E5%9B%B4%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20ALL%5B%22%E5%8F%AF%E8%83%BD%20scatter%20%E5%85%A8%E7%8E%AF%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"虚拟节点数少则不均匀，多则元数据大。一致性哈希不给外部一致，只给键放置。读己之写仍要会话。倾斜：热键仍打一点，要打散后缀或单独拆。",-1)),a[5]||(a[5]=e("p",null,"从 4 台扩到 5 台，两种分片各搬多少：",-1)),(s(),o(l,null,{default:E(()=>[i(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%BB%8E%204%20%E5%8F%B0%E6%89%A9%E5%88%B0%205%20%E5%8F%B0%22%5D%20--%3E%20MOD%5B%22%E6%A8%A1%20N%20%E5%88%86%E7%89%87%EF%BC%9Akey%20mod%20N%20%E5%85%A8%E5%8F%98%22%5D%0A%20%20MOD%20--%3E%20M1%5B%22%E7%BA%A6%E4%BA%94%E5%88%86%E4%B9%8B%E5%9B%9B%E7%9A%84%E9%94%AE%E9%87%8D%E6%96%B0%E6%98%A0%E5%B0%84%22%5D%0A%20%20M1%20--%3E%20M2%5B%22%E5%87%A0%E4%B9%8E%E5%85%A8%E9%87%8F%E6%90%AC%E5%AE%B6%E4%B8%8E%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20Q%20--%3E%20RING%5B%22%E7%8E%AF%E5%88%86%E7%89%87%EF%BC%9A%E5%8F%AA%E6%9C%89%E6%96%B0%E8%8A%82%E7%82%B9%E7%9A%84%E5%BC%A7%E6%98%93%E4%B8%BB%22%5D%0A%20%20RING%20--%3E%20R1%5B%22%E7%BA%A6%E4%BA%94%E5%88%86%E4%B9%8B%E4%B8%80%E7%9A%84%E9%94%AE%E6%90%AC%E5%AE%B6%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E5%85%B6%E4%BD%99%E9%94%AE%E5%8E%9F%E5%9C%B0%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">虚节点的数字感受：100 台物理机、每台放 100 个虚节点，环上就是 1 万个点，负载波动被摊到约 1% 的粒度；若每台只有 1 个点，运气差的机器可能比平均值多扛三成——虚节点是用更多元数据换均匀。</span></p><p>死锁：环不解决锁序。分片键课的热点病在环上变成单虚节点热。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比共享磁盘。也不把 DHT 动态成员当 Spanner 目录。RocksDB 是节点内引擎，后课。</p><p>后课默认：均匀写可用令牌环；范围查询慎用。无共享对共享存储：机器是否共用盘阵。</p><p>搬家量 \\(O(1/N)\\) 是环的卖点，不是查询卖点。</p><p><span class="marginnote">初学者容易把「一致性哈希」的「一致」读成分布式一致性（共识）。两者无关：这里的 consistent 只指加删节点时键的归属大体保持不变，与 Paxos 那套 consensus 是两个英文词、两码事——环上照样可能写入后立刻读到旧值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一致性哈希减加节点搬家；范围查询与事务不自动变好。</li><li>虚节点摊负载；热键仍要另拆。</li><li>无共享对共享存储下一课。</li><li>出处：Karger et al.；Cassandra；分片课。</li></ul>',9))])}const b=A(p,[["render",h]]);export{g as __pageData,b as default};
